// Synthetic bank identifiers/checksums only. No real banking or business records.
function finalIban(int $serial=1):string {$bban='11111111'.str_pad((string)$serial,10,'0',STR_PAD_LEFT);$number=$bban.'131400';$mod=0;foreach(str_split($number) as $n)$mod=($mod*10+(int)$n)%97;return 'DE'.str_pad((string)(98-$mod),2,'0',STR_PAD_LEFT).$bban;}
