function finalSeoCsv():string{return "punkt;breitengrad;laengengrad;position;wettbewerber;wettbewerber_position\na;50;8;1;Synthetic competitor;2\nb;50;8.01;4;;\nc;49.99;8;0;;\nd;49.99;8.01;3;;\n";}
